$ErrorActionPreference='Stop'
$repo=(Resolve-Path (Join-Path $PSScriptRoot '../..')).Path
$root=Join-Path $repo '.cache/behavior76/native-day-v7-r2'
. (Join-Path $PSScriptRoot 'authority-stream-reader-v2a.ps1')
Import-Issue76AuthorityStreamReader
function Hash([string]$p){(Get-FileHash -LiteralPath $p).Hash.ToLowerInvariant()}
function Create([string]$name,$object){$f=[IO.File]::Open((Join-Path $PSScriptRoot $name),[IO.FileMode]::CreateNew);try{$b=[Text.Encoding]::UTF8.GetBytes(($object|ConvertTo-Json -Depth 40)+"`n");$f.Write($b)}finally{$f.Dispose()};(Get-Item (Join-Path $PSScriptRoot $name)).IsReadOnly=$true}
function Json([string]$relative){ConvertFrom-Json ([IO.File]::ReadAllText([Issue76AuthorityStreamV2A]::SafePath($root,$relative))) -AsHashtable -Depth 80}
$idx=Json 'index.json';$manifest=Json 'manifest.json';$all=@([IO.File]::ReadLines((Join-Path $root 'behavior76_attempts.jsonl'))|Where-Object {$_.Trim()}|ForEach-Object {$_|ConvertFrom-Json -AsHashtable -Depth 80})
$current=@($all|Where-Object window_id -CEQ 'issue76-fixture-day-20261026T050548'|Sort-Object {[int]$_.n})
$inventory=@(Get-ChildItem -LiteralPath $root -File -Recurse|Sort-Object FullName|ForEach-Object {if($_.Name -match 'mapping'){throw 'Mapping must not be in raw root'};@{path=[IO.Path]::GetRelativePath($root,$_.FullName).Replace('\','/');bytes=$_.Length;sha256=(Hash $_.FullName)}})
Create 'native-day-v7-r2-independent-raw-inventory-v1.json' @{version='issue76-independent-raw-inventory-v1';files=$inventory}
$traces=[Collections.Generic.List[object]]::new();$owner=[Collections.Generic.List[object]]::new();$outcomes=[Collections.Generic.List[object]]::new();$auto=[Collections.Generic.List[string]]::new();$verified=0;$ordinal=0
foreach($c in $idx.episodes){
 $position=$ordinal++;$schedule=$manifest.schedule[[int][math]::Floor($position/2)];if($schedule.episode_id -cne $c.episode_id -or $schedule.arm_order[$position%2] -cne $c.masked_arm_id){throw 'Nonprefix or foreign schedule'}
 $dir=$c.tables_dir.Substring(0,$c.tables_dir.Length-7);$seal=Json ($dir+'/sealed-files.json');$listed=@{}
 foreach($f in $seal.files){if($listed.ContainsKey($f.path)){throw 'Duplicate seal'};$listed[$f.path]=$true;$p=[Issue76AuthorityStreamV2A]::SafePath($root,($dir+'/'+$f.path));if((Get-Item -LiteralPath $p).Length -ne $f.bytes -or (Hash $p) -cne $f.sha256){throw 'Case seal bytes changed'};$verified++}
 $actual=@(Get-ChildItem -LiteralPath (Join-Path $root $dir) -File -Recurse|Where-Object Name -CNE 'sealed-files.json');if($actual.Count -ne $seal.files.Count){throw 'Case seal not exact'}
 $h=Json ($dir+'/authority-trace.json');$q=Json ($dir+'/quiescence.json');$hpin=Hash (Join-Path $root ($dir+'/authority-trace.json'));$validation=$null
 if($h.sealed){$identity=@{window=$manifest.window;arm=$dir;schema=$q.schema;producer=$manifest.source;protocol_sha256=$manifest.protocol_sha256};$validation=Read-Issue76AuthorityStream (Join-Path $root $dir) $identity $hpin}
 $traces.Add(@{arm=$dir;header_sha256=$hpin;sealed=$h.sealed;event_count=$h.event_count;last_sequence=$h.last_sequence;segments=$h.segments.Count;tail_events=$h.tail.Count;open_spans=$h.open_spans;dropped_events=$h.dropped_events;operation_failures=$h.operation_failures;observer_failed=$h.observer_failed;validation=$validation;quiescence=$q})
 foreach($s in $c.steps){$o=Json $s.outcome_path;$outcomes.Add(@{arm=$dir;step_id=$s.step_id;state=$o.state;failure_phase=$o.failure_phase;safe_error_category=$o.safe_error_category;owner_input_id=$o.owner_input_id;owner_run_id=$o.owner_run_id;native_entry_ids=$o.native_entry_ids});if($s.step_id -in @('turn1','turn2')){$owner.Add(@{arm=$dir;step_id=$s.step_id;state=$o.state;owner_input_id=$o.owner_input_id;owner_run_id=$o.owner_run_id})};foreach($a in $o.automatic_run_ids){if(-not $auto.Contains($a)){$auto.Add($a)}}}
}
Create 'native-day-v7-r2-trace-metadata-v1.json' @{version='issue76-closed-stream-trace-metadata-v1';traces=$traces.ToArray();native_calls_by_checker=0;quality_assessed=$false}
$last=$current[-1];$lastMetadata=@{n=$last.n;slot=$last.slot;run_id=$last.run_id;kind=$last.kind;status=$last.status;stage=$last.stage;milliseconds=$last.milliseconds;input_tokens=$last.input_tokens;output_tokens=$last.output_tokens;total_tokens=$last.total_tokens;thinking_tokens=$last.thinking_tokens;model_version=$last.model_version;events=@($last.events|ForEach-Object {@{type=$_.type;error_code=$_.error_code;http_status=$_.http_status;safe_reason=$_.safe_reason}})}
$receipt=@{version='issue76-closed-day-v7-r2-raw-boundary-working-v1';window=$manifest.window;producer=$manifest.source;index_sha256=(Hash (Join-Path $root 'index.json'));manifest_sha256=(Hash (Join-Path $root 'manifest.json'));raw_files=$inventory.Count;raw_bytes=($inventory|Measure-Object bytes -Sum).Sum;raw_readonly=@(Get-ChildItem -LiteralPath $root -File -Recurse|Where-Object IsReadOnly).Count;independent_raw_inventory_sha256=(Hash (Join-Path $PSScriptRoot 'native-day-v7-r2-independent-raw-inventory-v1.json'));verified_case_files=$verified;indexed_arms=$idx.episodes.Count;complete_prefix_arms=0;planned_arms=48;planned_owner_opportunities=96;indexed_owner_outcomes=$owner.Count;actual_owner_inputs=@($owner|Where-Object {$_.owner_input_id}).Count;owner_outcome_states=@($owner|Group-Object state|ForEach-Object {@{state=$_.Name;count=$_.Count}});automatic_runs=$auto.Count;all_outcomes=$outcomes.ToArray();traces_metadata_sha256=(Hash (Join-Path $PSScriptRoot 'native-day-v7-r2-trace-metadata-v1.json'));native_admissions=$current.Count;measured=@($current|Where-Object {$null -ne $_.total_tokens}).Count;known_tokens=($current|Where-Object {$null -ne $_.total_tokens}|Measure-Object total_tokens -Sum).Sum;unknown_usage=@($current|Where-Object {$null -eq $_.total_tokens}).Count;all_rows=$all.Count;last_entry=$lastMetadata;mapping_read=$false;goldens_read=$false;quality_assessed=$false;complete=$false;qualification='NO_GO_INCOMPLETE_GLOBAL';native_calls_by_checker=0}
Create 'public-closed-day-v7-r2-raw-boundary-v1.json' $receipt
@{raw_files=$receipt.raw_files;raw_bytes=$receipt.raw_bytes;readonly=$receipt.raw_readonly;case_files_verified=$verified;arms=$idx.episodes.Count;owner_outcomes=$owner.Count;actual_owner_inputs=$receipt.actual_owner_inputs;owner_states=$receipt.owner_outcome_states;automatic_runs=$auto.Count;admissions=$current.Count;known_tokens=$receipt.known_tokens;unknown_usage=$receipt.unknown_usage;raw_boundary_receipt_sha256=(Hash (Join-Path $PSScriptRoot 'public-closed-day-v7-r2-raw-boundary-v1.json'))}|ConvertTo-Json -Depth 8
